def mc_estimate(samples) -> dict:
    x = np.asarray(samples, dtype=float)
    mean = x.mean()
    se = x.std(ddof=1) / np.sqrt(len(x))
    return {"mean": mean, "se": se, "ci_low": mean - 1.96 * se, "ci_high": mean + 1.96 * se}

