import numpy as np


def bayes_sequential(prior, likelihoods) -> np.ndarray:
    post = np.asarray(prior, dtype=float)
    rows = []
    for lik in np.asarray(likelihoods, dtype=float):
        post = post * lik
        post = post / post.sum()
        rows.append(post)
    return np.array(rows)

