import math


def derangements(n: int) -> tuple:
    a, b = 1, 0  # D(0), D(1)
    if n == 0:
        return 1, 1.0
    for k in range(2, n + 1):
        a, b = b, (k - 1) * (a + b)
    return b, b / math.factorial(n)

