def cash_and_carry(S: float, F_market: float, r: float, q: float, T: float) -> dict:
    fair = S * np.exp((r - q) * T)
    diff = F_market - fair
    strategy = "none" if abs(diff) < 1e-9 else ("cash_and_carry" if diff > 0 else "reverse")
    return {"fair": fair, "strategy": strategy, "profit": abs(diff)}

