import numpy as np


def strategy_profit(legs: list, S_T) -> np.ndarray:
    S = np.asarray(S_T, dtype=float)
    total = np.zeros_like(S)
    for leg in legs:
        if leg["type"] == "call":
            payoff = np.maximum(S - leg["strike"], 0)
        elif leg["type"] == "put":
            payoff = np.maximum(leg["strike"] - S, 0)
        else:
            payoff = S
        total += leg["qty"] * (payoff - leg["premium"])
    return total

