def bollinger_positions(prices: pd.Series, window: int = 20, entry: float = 2.0, exit: float = 0.5) -> pd.Series:
    z = (prices - prices.rolling(window).mean()) / prices.rolling(window).std()
    pos, out = 0, []
    for v in z.to_numpy():
        if np.isnan(v):
            pos = 0
        else:
            if (pos == 1 and v >= -exit) or (pos == -1 and v <= exit):
