            "spread_pnl": attr["spread"].sum(), "inventory_pnl": attr["inventory"].sum(), "total_pnl": sim["pnl"].iloc[-1],
            "fills": int(traded.sum()), "inventory_std": sim["inventory"].std(),
            "markout_informed": mk["informed"], "markout_uninformed": mk["uninformed"]}

